import * as fs from 'fs/promises';
import { allureConfig } from './src/config/reporting';

/**
 * Run-start hygiene: empties the Allure results directory, so the report generated by
 * `src/utils/AllureReport.ts` never mixes runs. Only this raw staging directory is cleared;
 * published HTML (`reports/`) and immutable evidence (`.harness/runs/allure/`) stay.
 *
 * Runs once per run, outside any worker — no `test.step()`, `test.info()` or attachments here.
 * A failed clear would merge stale results into the new report, so the error is rethrown.
 */
module.exports = async () => {
  const resultsDir = allureConfig.resultsDir;
  try {
    await fs.rm(resultsDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
    await fs.mkdir(resultsDir, { recursive: true });
    console.log(`Allure results directory cleared: ${resultsDir}`);
  } catch (error) {
    console.error(`Failed to clear the Allure results directory: ${resultsDir}`, error);
    throw error;
  }
};
